module seq_fsm (
    input  logic clk,
    input  logic rst_n,
    input  logic start,
    input  logic bit_in,
    output logic valid
);

    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        DETECT = 2'b01,
        DONE   = 2'b10
    } state_t;

    state_t state, next_state;

    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= IDLE;
        end else begin
            state <= next_state;
        end
    end

    always_comb begin
        next_state = state;
        case (state)
            IDLE: begin
                if (start == 1'b1) begin
                    next_state = DETECT;
                end
            end
            DETECT: begin
                if (bit_in == 1'b1) begin
                    next_state = DONE;
                end else begin
                    next_state = IDLE;
                end
            end
            DONE: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    assign valid = (state == DONE);

endmodule
